parameters.query:
SELECT product_code, description, uom, currency, list_unit_price, min_order_qty, lead_time_days, bulk_tiers
FROM products
WHERE product_code = $1;

parameters.jsCode:
// The DB returned the authoritative product row (or nothing). Compute the
// bulk-tender price deterministically. The qty came from the request, the
// list price and tiers came from the DB — the LLM touches none of it.

const rows = $input.all();
const req = $('Incoming Request').first().json;

if (rows.length === 0) {
  return [{ json: { found: false, product_code: req.product_code, qty: req.qty, customer: req.customer } }];
}

const p = rows[0].json;
const tiers = typeof p.bulk_tiers === 'string' ? JSON.parse(p.bulk_tiers) : p.bulk_tiers;
const listUnit = Number(p.list_unit_price);

let discount = 0;
for (const t of tiers) { if (req.qty >= t.min_qty) discount = t.discount_pct; }

const netUnit = Number((listUnit * (1 - discount / 100)).toFixed(2));
const lineTotal = Number((netUnit * req.qty).toFixed(2));
const savings = Number(((listUnit - netUnit) * req.qty).toFixed(2));

return [{ json: {
  found: true,
  customer: req.customer,
  product_code: p.product_code,
  description: p.description,
  uom: p.uom,
  currency: p.currency,
  qty: req.qty,
  min_order_qty: p.min_order_qty,
  below_min_order_qty: req.qty < p.min_order_qty,
  list_unit_price: listUnit,
  applied_discount_pct: discount,
  net_unit_price: netUnit,
  line_total: lineTotal,
  total_savings: savings,
  lead_time_days: p.lead_time_days
} }];
